import sys
import math

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.mod = 998244353

        def add(self, a, b):
            return (a + b) % self.mod

        def subtract(self, a, b):
            return (a - b) % self.mod

        def mult(self, a, b, inv_b=None):
            if inv_b is not None:
                return (a * inv_b) % self.mod
            else:
                return (a * b) % self.mod

        def smallInv(self, a):
            # Fermat's little theorem for modular inverse
            return pow(a, self.mod - 2, self.mod)

        def fInv(self, n):
            # Placeholder for factorial inverse precomputation if needed
            pass

        def ncr(self, n, r):
            # Compute n choose r modulo mod
            if r < 0 or r > n:
                return 0
            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = (numerator * (n - i)) % self.mod
                denominator = (denominator * (i + 1)) % self.mod
            return (numerator * self.smallInv(denominator)) % self.mod

class InputReader:
    def __init__(self, stream):
        self.stream = stream
        self.tokens = []

    def next(self):
        while not self.tokens:
            line = self.stream.readline()
            if not line:
                raise Exception("End of input")
            self.tokens = line.strip().split()
        return self.tokens.pop(0)

    def nextInt(self):
        return int(self.next())

class HZSShufflesCards:
    def __init__(self):
        self.mod = NumberTheory.Mod998()

    def solve(self, testNumber, in_reader, out):
        n = in_reader.nextInt()
        m = in_reader.nextInt()

        self.mod.fInv(n + m)

        phaseSize = 1
        p = 1
        i = 0
        while p != 0:
            p = self.mod.mult(p, n - i, self.mod.smallInv(n + m - i))
            phaseSize = self.mod.add(phaseSize, p)
            i += 1

        answer = 0
        for k in range(1, n + 1):
            numPhases = self.mod.mult(m + k, self.mod.smallInv(k))
            e = self.mod.mult(numPhases, phaseSize)
            term = self.mod.mult(self.mod.ncr(n, k), e)

            if k % 2 == 1:
                answer = self.mod.add(answer, term)
            else:
                answer = self.mod.subtract(answer, term)

        out.write(str(answer) + "\n")

def main():
